import{_ as i,l as n,o as e,c as l,v as r,p as s,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"股东激进主义","description":"","frontmatter":{"title":"股东激进主义","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/shareholder-activism.md","filePath":"econ/shareholder-activism.md","lastUpdated":1789023840000}'),c={name:"econ/shareholder-activism.md"};function E(m,a,A,_,B,u){const t=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="股东激进主义" tabindex="-1">股东激进主义 <a class="header-anchor" href="#股东激进主义" aria-label="Permalink to &quot;股东激进主义&quot;">​</a></h1><div class="epigraph"><p>积极股东付监测成本、积攒投票权、逼董事会改杠杆或换经理；收益部分外溢给搭便车的被动股东，因此积极主义只会不足，不会过多——除非另有私人收益。</p><footer>—— 据 Shleifer and Vishny, Large Shareholders and Corporate Control, Journal of Political Economy 1986；Brav, Jiang, Partnoy and Thomas, Journal of Finance 2008</footer></div><p><a href="/econ/executive-compensation">上一课</a>把内部合同写完。本课缺口是外部大股东与对冲基金激进主义：谁付监督成本，以及干预是价值还是转移。不重做薪酬一阶条件，不把 Grossman–Hart 要约收购提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>董事会可能被俘获，薪酬可能是租金。Shleifer–Vishny：大股东有激励监测，因为现金流权够大。代价是不分散的风险与可能的私人收益（掏空）。对冲基金激进主义是短期积攒的少数股权加公开施压、代理权争夺，不是全面收购。Brav 等描述干预手段与公告回报。缺口是：分散股权下监督是公共品，激进主义者提供公共品并试图用公告升值获利；若升值全外溢，激励不足。这与后课接管免费搭车同构，程度更轻（不必买到 100%）。</p><p><span class="marginnote">搭便车：被动指数基金享受治理改善却不付干预成本。基金业结构改变谁能当激进者。本课不写资产管理机构的微观结构。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>干预菜单：要求回购与加杠杆（Jensen FCF）、换董事、分拆、换 CEO、限制并购。价值假说：降低代理成本。转移假说：把债权人、雇员、客户的准租转给股东，或短期推高股价便于减持。债务契约与评级悬崖会约束「加杠杆」菜单——债权单元刚写完。</p><p>与关系：激进主义是公开的硬信息干预；关系银行是私下。对象常是成熟、低托宾 Q、高现金——Jensen 样本，不是融资约束成长企业。</p>',9)),(e(),s(p,null,{default:o(()=>[h(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20DISP%5B%22%E8%82%A1%E6%9D%83%E5%88%86%E6%95%A3%22%5D%20--%3E%20FREE%5B%22%E7%9B%91%E7%9D%A3%E5%85%AC%E5%85%B1%E5%93%81%22%5D%0A%20%20ACT%5B%22%E7%A7%AF%E6%94%92%E6%8A%95%E7%A5%A8%20%2B%20%E5%A3%B0%22%5D%20--%3E%20INT%5B%22%E5%B9%B2%E9%A2%84%22%5D%0A%20%20INT%20--%3E%20VAL%5B%22%E9%99%8D%E4%BB%A3%E7%90%86%E6%88%90%E6%9C%AC%22%5D%0A%20%20INT%20--%3E%20TRF%5B%22%E8%BD%AC%E7%A7%BB%E5%87%86%E7%A7%9F%22%5D%0A%20%20PASS%5B%22%E8%A2%AB%E5%8A%A8%E8%82%A1%E4%B8%9C%22%5D%20--%3E%20RIDE%5B%22%E6%90%AD%E4%BE%BF%E8%BD%A6%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>公告正回报不自动等于社会有效：可以是转移。识别课会提事件研究的问题。本课只要两种机制并列。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把董事会议价外移。激进股东改变董事提名池，削弱 Hermalin–Weisbach 的经理俘获。成本：错误干预、打断顾问功能、迫使削减正 NPV 的长期投资（实物期权被提前执行或放弃）。薪酬合同若已高能激励，再加外部压力可能重复或冲突。</p><p>与择时：激进主义要求在低估时回购，像反向 Baker–Wurgler。若市场有效，回购只改切片；若无效或代理，则改 \\(V\\)。</p><h3 id="不是「基金都是短视的」" tabindex="-1">不是「基金都是短视的」 <a class="header-anchor" href="#不是「基金都是短视的」" aria-label="Permalink to &quot;不是「基金都是短视的」&quot;">​</a></h3><p>持有期数据与合约形式（13D）比标签重要。短视假说要证明被砍的是正 NPV 而不是 FCF 浪费。Tirole：可验证的派息容易被要求，不可验证的长期项目容易被牺牲——又是多任务。</p><p><span class="marginnote">Gillan–Starks 等区分公共养老基金与对冲基金的手段。机制同是投票与声，私人收益与视野不同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把本课写成 13D 案例集。下一课：全面接管时搭便车更致命，Grossman–Hart 给出要约必须留下利润才有人付溢价。激进主义是部分收购加语音，不是要约收购全文。</p><p>后课默认：积极股东提供公共监督，激励因搭便车而不足；干预有价值与转移两读。对象偏向 FCF 企业。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>大股东/激进基金付监测成本，被动股东搭便车，故积极主义供给不足。</li><li>菜单是杠杆、董事、资产重组；价值对转移要并列。</li><li>与内部薪酬、董事会互补，不是替代一切合同。</li><li>出处：Shleifer and Vishny, <em>JPE</em> 1986；Brav, Jiang, Partnoy and Thomas, <em>JF</em> 2008。</li></ul>',12))])}const D=i(c,[["render",E]]);export{T as __pageData,D as default};
